fun exportBackupJson(onResult: (String) -> Unit) {
    viewModelScope.launch {
        val payload = DataBackupPayload(
            profiles = profileRepository.getActiveSnapshot().map { it.toBackupItem() },
            medications = medicationRepository.getActiveSnapshot().map { it.toBackupItem() },
            doseLogs = doseLogRepository.getAllSnapshot().map { it.toBackupItem() },
        )
        onResult(DataBackupValidator.serialize(payload))
    }
}
